package com.cazsius.solcarrot;

import com.cazsius.solcarrot.tracking.CapabilityHandler;
import com.cazsius.solcarrot.tracking.FoodList;
import com.google.common.collect.Lists;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.Item;
import net.minecraftforge.common.ForgeConfigSpec;
import net.minecraftforge.common.ForgeConfigSpec.BooleanValue;
import net.minecraftforge.common.ForgeConfigSpec.Builder;
import net.minecraftforge.common.ForgeConfigSpec.ConfigValue;
import net.minecraftforge.common.ForgeConfigSpec.IntValue;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.ModLoadingContext;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.config.ModConfig;
import net.minecraftforge.fml.event.config.ModConfigEvent;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.server.ServerLifecycleHooks;
import org.apache.commons.lang3.tuple.Pair;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;

import static net.minecraftforge.fml.common.Mod.EventBusSubscriber.Bus.MOD;

@Mod.EventBusSubscriber(modid = SOLCarrot.MOD_ID, bus = MOD)
public final class SOLCarrotConfig {
	private static String localizationPath(String path) {
		return "config." + SOLCarrot.MOD_ID + "." + path;
	}

	public static final Server SERVER;
	public static final ForgeConfigSpec SERVER_SPEC;

	static {
		Pair<Server, ForgeConfigSpec> specPair = new Builder().configure(Server::new);
		SERVER = specPair.getLeft();
		SERVER_SPEC = specPair.getRight();
	}

	public static final Client CLIENT;
	public static final ForgeConfigSpec CLIENT_SPEC;

	static {
		Pair<Client, ForgeConfigSpec> specPair = new Builder().configure(Client::new);
		CLIENT = specPair.getLeft();
		CLIENT_SPEC = specPair.getRight();
	}

	public static void setUp() {
		ModLoadingContext context = ModLoadingContext.get();
		context.registerConfig(ModConfig.Type.SERVER, SERVER_SPEC);
		context.registerConfig(ModConfig.Type.CLIENT, CLIENT_SPEC);
	}

	@SubscribeEvent
	public static void onConfigReload(ModConfigEvent.Reloading event) {
		MinecraftServer currentServer = ServerLifecycleHooks.getCurrentServer();
		if (currentServer == null) return;

		var players = currentServer.getPlayerList();
		for (var player : players.getPlayers()) {
			FoodList.get(player).invalidateProgressInfo();
			CapabilityHandler.syncFoodList(player);
		}
	}

	public static int getBaseHearts() {
		return SERVER.baseHearts.get();
	}

	public static int getHeartsPerMilestone() {
		return SERVER.heartsPerMilestone.get();
	}

	public static List<Integer> getMilestones() {
		return new ArrayList<>(SERVER.milestones.get());
	}

	public static List<String> getBlacklist() {
		return new ArrayList<>(SERVER.blacklist.get());
	}

	public static List<String> getWhitelist() {
		return new ArrayList<>(SERVER.whitelist.get());
	}

	public static int getMinimumFoodValue() {
		return SERVER.minimumFoodValue.get();
	}

	public static boolean shouldResetOnDeath() {
		return SERVER.shouldResetOnDeath.get();
	}

	public static boolean limitProgressionToSurvival() {
		return SERVER.limitProgressionToSurvival.get();
	}

	public static class Server {
		public final IntValue baseHearts;
		public final IntValue heartsPerMilestone;
		public final ConfigValue<List<? extends Integer>> milestones;

		public final ConfigValue<List<? extends String>> blacklist;
		public final ConfigValue<List<? extends String>> whitelist;
		public final IntValue minimumFoodValue;

		public final BooleanValue shouldResetOnDeath;
		public final BooleanValue limitProgressionToSurvival;

		Server(Builder builder) {
			builder.push("milestones");

			baseHearts = builder
				.translation(localizationPath("base_hearts"))
				.comment("Number of hearts you start out with.")
				.defineInRange("baseHearts", 10, 0, 1000);

			heartsPerMilestone = builder
				.translation(localizationPath("hearts_per_milestone"))
				.comment("Number of hearts you gain for reaching a new milestone.")
				.defineInRange("heartsPerMilestone", 2, 0, 1000);

			milestones = builder
				.translation(localizationPath("milestones"))
				.comment("A list of numbers of unique foods you need to eat to unlock each milestone, in ascending order. Naturally, adding more milestones lets you earn more hearts.")
				.defineList("milestones", Lists.newArrayList(5, 10, 15, 20, 25), e -> e instanceof Integer);

			builder.pop();
			builder.push("filtering");

			blacklist = builder
				.translation(localizationPath("blacklist"))
				.comment("Foods in this list won't affect the player's health nor show up in the food book.")
				.defineList("blacklist", Lists.newArrayList(), e -> e instanceof String);

			whitelist = builder
				.translation(localizationPath("whitelist"))
				.comment("When this list contains anything, the blacklist is ignored and instead only foods from here count.")
				.defineList("whitelist", Lists.newArrayList(), e -> e instanceof String);

			minimumFoodValue = builder
				.translation(localizationPath("minimum_food_value"))
				.comment("The minimum hunger value foods need to provide in order to count for milestones, in half drumsticks.")
				.defineInRange("minimumFoodValue", 1, 0, 1000);

			builder.pop();
			builder.push("miscellaneous");

			shouldResetOnDeath = builder
				.translation(localizationPath("reset_on_death"))
				.comment("Whether or not to reset the food list on death, effectively losing all bonus hearts.")
				.define("resetOnDeath", false);

			limitProgressionToSurvival = builder
				.translation(localizationPath("limit_progression_to_survival"))
				.comment("If true, eating foods outside of survival mode (e.g. creative/adventure) is not tracked and thus does not contribute towards progression.")
				.define("limitProgressionToSurvival", false);

			builder.pop();
		}
	}

	public static boolean shouldPlayMilestoneSounds() {
		return CLIENT.shouldPlayMilestoneSounds.get();
	}

	public static boolean shouldSpawnIntermediateParticles() {
		return CLIENT.shouldSpawnIntermediateParticles.get();
	}

	public static boolean shouldSpawnMilestoneParticles() {
		return CLIENT.shouldSpawnMilestoneParticles.get();
	}

	public static boolean isFoodTooltipEnabled() {
		return CLIENT.isFoodTooltipEnabled.get();
	}

	public static boolean shouldShowProgressAboveHotbar() {
		return CLIENT.shouldShowProgressAboveHotbar.get();
	}

	public static boolean shouldShowUneatenFoods() {
		return CLIENT.shouldShowUneatenFoods.get();
	}

	public static class Client {
		public final BooleanValue shouldPlayMilestoneSounds;
		public final BooleanValue shouldSpawnIntermediateParticles;
		public final BooleanValue shouldSpawnMilestoneParticles;

		public final BooleanValue isFoodTooltipEnabled;
		public final BooleanValue shouldShowProgressAboveHotbar;
		public final BooleanValue shouldShowUneatenFoods;

		Client(Builder builder) {
			builder.push("milestone celebration");

			shouldPlayMilestoneSounds = builder
				.translation(localizationPath("should_play_milestone_sounds"))
				.comment("If true, reaching a new milestone plays a ding sound.")
				.define("shouldPlayMilestoneSounds", true);

			shouldSpawnIntermediateParticles = builder
				.translation(localizationPath("should_spawn_intermediate_particles"))
				.comment("If true, trying a new food spawns particles.")
				.define("shouldSpawnIntermediateParticles", true);

			shouldSpawnMilestoneParticles = builder
				.translation(localizationPath("should_spawn_milestone_particles"))
				.comment("If true, reaching a new milestone spawns particles.")
				.define("shouldSpawnMilestoneParticles", true);

			builder.pop();
			builder.push("miscellaneous");

			isFoodTooltipEnabled = builder
				.translation(localizationPath("is_food_tooltip_enabled"))
				.comment("If true, foods indicate in their tooltips whether or not they have been eaten.")
				.define("isFoodTooltipEnabled", true);

			shouldShowProgressAboveHotbar = builder
				.translation(localizationPath("should_show_progress_above_hotbar"))
				.comment("Whether the messages notifying you of reaching new milestones should be displayed above the hotbar or in chat.")
				.define("shouldShowProgressAboveHotbar", true);

			shouldShowUneatenFoods = builder
				.translation(localizationPath("should_show_uneaten_foods"))
				.comment("If true, the food book also lists foods that you haven't eaten, in addition to the ones you have.")
				.define("shouldShowUneatenFoods", true);

			builder.pop();
		}
	}

	// TODO: investigate performance of all these get() calls

	public static int milestone(int i) {
		return SERVER.milestones.get().get(i);
	}

	public static int getMilestoneCount() {
		return SERVER.milestones.get().size();
	}

	public static int highestMilestone() {
		return milestone(getMilestoneCount() - 1);
	}

	public static boolean hasWhitelist() {
		return !SERVER.whitelist.get().isEmpty();
	}

	public static boolean isAllowed(Item food) {
		String id = Objects.requireNonNull(ForgeRegistries.ITEMS.getKey(food)).toString();
		if (hasWhitelist()) {
			return matchesAnyPattern(id, SERVER.whitelist.get());
		} else {
			return !matchesAnyPattern(id, SERVER.blacklist.get());
		}
	}

	public static boolean shouldCount(Item food) {
		return isHearty(food) && isAllowed(food);
	}

	public static boolean isHearty(Item food) {
		var foodInfo = food.getFoodProperties();
		if (foodInfo == null) return false;
		return foodInfo.getNutrition() >= SERVER.minimumFoodValue.get();
	}

	private static boolean matchesAnyPattern(String query, Collection<? extends String> patterns) {
		for (String glob : patterns) {
			StringBuilder pattern = new StringBuilder(glob.length());
			for (String part : glob.split("\\*", -1)) {
				if (!part.isEmpty()) { // not necessary
					pattern.append(Pattern.quote(part));
				}
				pattern.append(".*");
			}

			// delete extraneous trailing ".*" wildcard
			pattern.delete(pattern.length() - 2, pattern.length());

			if (Pattern.matches(pattern.toString(), query)) {
				return true;
			}
		}
		return false;
	}
}

package com.cazsius.solcarrot.communication;

import com.cazsius.solcarrot.tracking.FoodList;
import net.minecraft.client.Minecraft;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.fml.DistExecutor;
import net.minecraftforge.network.NetworkEvent;

import java.util.function.Supplier;

public final class FoodListMessage {
	private CompoundTag capabilityNBT;

	public FoodListMessage(FoodList foodList) {
		this.capabilityNBT = foodList.serializeNBT();
	}

	public FoodListMessage(FriendlyByteBuf buffer) {
		this.capabilityNBT = buffer.readNbt();
	}

	public void write(FriendlyByteBuf buffer) {
		buffer.writeNbt(capabilityNBT);
	}

	public void handle(Supplier<NetworkEvent.Context> context) {
		DistExecutor.unsafeRunWhenOn(Dist.CLIENT, () -> () -> Handler.handle(this, context));
	}

	private static class Handler {
		static void handle(FoodListMessage message, Supplier<NetworkEvent.Context> context) {
			context.get().enqueueWork(() -> {
				Player player = Minecraft.getInstance().player;
				assert player != null;
				FoodList.get(player).deserializeNBT(message.capabilityNBT);
			});
			context.get().setPacketHandled(true);
		}
	}
}

package com.cazsius.solcarrot.tracking;

import com.cazsius.solcarrot.SOLCarrot;
import com.cazsius.solcarrot.SOLCarrotConfig;
import com.cazsius.solcarrot.api.FoodCapability;
import com.cazsius.solcarrot.communication.FoodListMessage;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.common.capabilities.RegisterCapabilitiesEvent;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.network.NetworkDirection;

import static net.minecraftforge.fml.common.Mod.EventBusSubscriber.Bus.MOD;

@Mod.EventBusSubscriber(modid = SOLCarrot.MOD_ID)
public final class CapabilityHandler {
	private static final ResourceLocation FOOD = SOLCarrot.resourceLocation("food");

	@Mod.EventBusSubscriber(modid = SOLCarrot.MOD_ID, bus = MOD)
	private static final class Setup {
		@SubscribeEvent
		public static void registerCapabilities(RegisterCapabilitiesEvent event) {
			event.register(FoodCapability.class);
		}
	}

	@SubscribeEvent
	public static void attachPlayerCapability(AttachCapabilitiesEvent<Entity> event) {
		if (!(event.getObject() instanceof Player)) return;

		event.addCapability(FOOD, new FoodList());
	}

	@SubscribeEvent
	public static void onPlayerLogin(PlayerEvent.PlayerLoggedInEvent event) {
		// server needs to send any loaded data to the client
		syncFoodList(event.getEntity());
	}

	@SubscribeEvent
	public static void onPlayerDimensionChange(PlayerEvent.PlayerChangedDimensionEvent event) {
		syncFoodList(event.getEntity());
	}

	@SubscribeEvent
	public static void onClone(PlayerEvent.Clone event) {
		if (event.isWasDeath() && SOLCarrotConfig.shouldResetOnDeath()) return;

		var originalPlayer = event.getOriginal();
		originalPlayer.reviveCaps(); // so we can access the capabilities; entity will get removed either way
		var original = FoodList.get(originalPlayer);
		var newInstance = FoodList.get(event.getEntity());
		newInstance.deserializeNBT(original.serializeNBT());
		// can't sync yet; client hasn't attached capabilities yet

		originalPlayer.invalidateCaps();
	}

	@SubscribeEvent
	public static void onPlayerRespawn(PlayerEvent.PlayerRespawnEvent event) {
		syncFoodList(event.getEntity());
	}

	public static void syncFoodList(Player player) {
		if (player.level().isClientSide) return;

		var target = (ServerPlayer) player;
		SOLCarrot.channel.sendTo(
			new FoodListMessage(FoodList.get(player)),
			target.connection.connection,
			NetworkDirection.PLAY_TO_CLIENT
		);

		MaxHealthHandler.updateFoodHPModifier(player);
	}
}

package com.cazsius.solcarrot.tracking;

import com.cazsius.solcarrot.SOLCarrot;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.Item;
import net.minecraftforge.registries.ForgeRegistries;

import javax.annotation.Nullable;
import java.util.Optional;

public final class FoodInstance {
	public final Item item;

	public FoodInstance(Item item) {
		this.item = item;
	}

	@Nullable
	public static FoodInstance decode(String encoded) {
		ResourceLocation name = new ResourceLocation(encoded);

		// TODO it'd be nice to store (and maybe even count) references to missing items, in case the mod is added back in later
		Item item = ForgeRegistries.ITEMS.getValue(name);
		if (item == null) {
			SOLCarrot.LOGGER.warn("attempting to load item into food list that is no longer registered: " + encoded + " (removing from list)");
			return null;
		}

		if (!item.isEdible()) {
			SOLCarrot.LOGGER.warn("attempting to load item into food list that is no longer edible: " + encoded + " (ignoring in case it becomes edible again later)");
		}

		return new FoodInstance(item);
	}

	@Nullable
	public String encode() {
		return Optional.ofNullable(ForgeRegistries.ITEMS.getKey(item))
			.map(ResourceLocation::toString)
			.orElse(null);
	}

	@Override
	public int hashCode() {
		return item.hashCode();
	}

	@Override
	public boolean equals(Object obj) {
		if (!(obj instanceof FoodInstance other)) return false;

		return item.equals(other.item);
	}

	public Item getItem() {
		return item;
	}
}

package com.cazsius.solcarrot.tracking;

import com.cazsius.solcarrot.SOLCarrotConfig;
import com.cazsius.solcarrot.api.FoodCapability;
import com.cazsius.solcarrot.api.SOLCarrotAPI;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.StringTag;
import net.minecraft.nbt.Tag;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.util.LazyOptional;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

@ParametersAreNonnullByDefault
public final class FoodList implements FoodCapability {
	private static final String NBT_KEY_FOOD_LIST = "foodList";

	public static FoodList get(Player player) {
		return (FoodList) player.getCapability(SOLCarrotAPI.foodCapability)
			.orElseThrow(FoodListNotFoundException::new);
	}

	private final Set<FoodInstance> foods = new HashSet<>();

	@Nullable
	private ProgressInfo cachedProgressInfo;

	public FoodList() {}

	private final LazyOptional<FoodList> capabilityOptional = LazyOptional.of(() -> this);

	@Override
	public <T> LazyOptional<T> getCapability(Capability<T> capability, @Nullable Direction side) {
		return capability == SOLCarrotAPI.foodCapability ? capabilityOptional.cast() : LazyOptional.empty();
	}

	/** used for persistent storage */
	@Override
	public CompoundTag serializeNBT() {
		var tag = new CompoundTag();

		var list = new ListTag();
		foods.stream()
			.map(FoodInstance::encode)
			.filter(Objects::nonNull)
			.map(StringTag::valueOf)
			.forEach(list::add);
		tag.put(NBT_KEY_FOOD_LIST, list);

		return tag;
	}

	/** used for persistent storage */
	@Override
	public void deserializeNBT(CompoundTag tag) {
		var list = tag.getList(NBT_KEY_FOOD_LIST, Tag.TAG_STRING);

		foods.clear();
		list.stream()
			.map(nbt -> (StringTag) nbt)
			.map(StringTag::getAsString)
			.map(FoodInstance::decode)
			.filter(Objects::nonNull)
			.forEach(foods::add);

		invalidateProgressInfo();
	}

	/** @return true if the food was not previously known, i.e. if a new food has been tried */
	public boolean addFood(Item food) {
		boolean wasAdded = foods.add(new FoodInstance(food)) && SOLCarrotConfig.shouldCount(food);
		invalidateProgressInfo();
		return wasAdded;
	}

	@Override
	public boolean hasEaten(Item food) {
		if (!food.isEdible()) return false;
		return foods.contains(new FoodInstance(food));
	}

	public void clearFood() {
		foods.clear();
		invalidateProgressInfo();
	}

	public Set<FoodInstance> getEatenFoods() {
		return new HashSet<>(foods);
	}

	// TODO: is this actually desirable? it doesn't filter at all
	@Override
	public int getEatenFoodCount() {
		return foods.size();
	}

	public ProgressInfo getProgressInfo() {
		if (cachedProgressInfo == null) {
			cachedProgressInfo = new ProgressInfo(this);
		}
		return cachedProgressInfo;
	}

	public void invalidateProgressInfo() {
		cachedProgressInfo = null;
	}

	public static class FoodListNotFoundException extends RuntimeException {
		public FoodListNotFoundException() {
			super("Player must have food capability attached, but none was found.");
		}
	}
}

package com.cazsius.solcarrot.tracking;

import com.cazsius.solcarrot.SOLCarrot;
import com.cazsius.solcarrot.SOLCarrotConfig;
import net.minecraft.ChatFormatting;
import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.multiplayer.ClientPacketListener;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.network.protocol.game.ClientboundLevelParticlesPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.GameType;
import net.minecraftforge.event.entity.living.LivingEntityUseItemEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import static com.cazsius.solcarrot.lib.Localization.localizedComponent;
import static com.cazsius.solcarrot.lib.Localization.localizedQuantityComponent;

@Mod.EventBusSubscriber(modid = SOLCarrot.MOD_ID)
public final class FoodTracker {
	@SubscribeEvent
	public static void onFoodEaten(LivingEntityUseItemEvent.Finish event) {
		if (!(event.getEntity() instanceof Player player)) return;

		var isClientSide = player.level().isClientSide;

		if (SOLCarrotConfig.limitProgressionToSurvival() && player.isCreative()) return;

		var usedItem = event.getItem().getItem();
		if (!usedItem.isEdible()) return;

		FoodList foodList = FoodList.get(player);
		boolean hasTriedNewFood = foodList.addFood(usedItem);

		// check this before syncing, because the sync entails an hp update
		boolean newMilestoneReached = MaxHealthHandler.updateFoodHPModifier(player);

		CapabilityHandler.syncFoodList(player);
		var progressInfo = foodList.getProgressInfo();

		if (newMilestoneReached) {
			if (isClientSide && SOLCarrotConfig.shouldPlayMilestoneSounds()) {
				// passing the player makes it not play for some reason
				player.level().playSound(
					player,
					player.blockPosition(),
					SoundEvents.PLAYER_LEVELUP, SoundSource.PLAYERS,
					1.0F, 1.0F
				);
			}

			if (isClientSide && SOLCarrotConfig.shouldSpawnMilestoneParticles()) {
				spawnParticles(player, ParticleTypes.HEART, 12);

				if (progressInfo.hasReachedMax()) {
					spawnParticles(player, ParticleTypes.HAPPY_VILLAGER, 16);
				}
			}

			var heartsDescription = localizedQuantityComponent("message", "hearts", SOLCarrotConfig.getHeartsPerMilestone());

			if (isClientSide && SOLCarrotConfig.shouldShowProgressAboveHotbar()) {
				String messageKey = progressInfo.hasReachedMax() ? "finished.hotbar" : "milestone_achieved";
				player.displayClientMessage(localizedComponent("message", messageKey, heartsDescription), true);
			} else {
				showChatMessage(player, ChatFormatting.DARK_AQUA, localizedComponent("message", "milestone_achieved", heartsDescription));
				if (progressInfo.hasReachedMax()) {
					showChatMessage(player, ChatFormatting.GOLD, localizedComponent("message", "finished.chat"));
				}
			}
		} else if (hasTriedNewFood) {
			if (isClientSide && SOLCarrotConfig.shouldSpawnIntermediateParticles()) {
				spawnParticles(player, ParticleTypes.END_ROD, 12);
			}
		}
	}

	private static void spawnParticles(Player player, ParticleOptions type, int count) {
		// hacky way to reuse the existing logic for randomizing particle spawn positions
		var connection = Minecraft.getInstance().getConnection();
		assert connection != null;
		connection.handleParticleEvent(new ClientboundLevelParticlesPacket(
			type, false,
			player.getX(), player.getY() + player.getEyeHeight(), player.getZ(),
			0.5F, 0.5F, 0.5F,
			0.0F, count
		));
	}

	private static void showChatMessage(Player player, ChatFormatting color, Component message) {
		var component = localizedComponent("message", "chat_wrapper", message)
			.withStyle(color);
		player.displayClientMessage(component, false);
	}

	private FoodTracker() {}
}

package com.cazsius.solcarrot.tracking;

import com.cazsius.solcarrot.SOLCarrot;
import com.cazsius.solcarrot.SOLCarrotConfig;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.ModList;
import net.minecraftforge.fml.common.Mod;

import javax.annotation.Nullable;
import java.util.Objects;
import java.util.UUID;

@Mod.EventBusSubscriber(modid = SOLCarrot.MOD_ID)
public final class MaxHealthHandler {
	private static final boolean HAS_FIRST_AID = ModList.get().isLoaded("firstaid");
	private static final UUID MILESTONE_HEALTH_MODIFIER_ID = UUID.fromString("b20d3436-0d39-4868-96ab-d0a4856e68c6");

	@SubscribeEvent
	public static void onPlayerLogin(PlayerEvent.PlayerLoggedInEvent event) {
		updateFoodHPModifier(event.getEntity());
	}

	@SubscribeEvent
	public static void onPlayerClone(PlayerEvent.Clone event) {
		var prevModifier = getHealthModifier(event.getOriginal());
		if (prevModifier == null) return;

		updateHealthModifier(event.getEntity(), prevModifier);
	}

	/** @return whether the player reached a new milestone in this update */
	public static boolean updateFoodHPModifier(Player player) {
		var prevModifier = getHealthModifier(player);

		int healthPenalty = 2 * (SOLCarrotConfig.getBaseHearts() - 10);

		ProgressInfo progressInfo = FoodList.get(player).getProgressInfo();
		int milestonesAchieved = progressInfo.milestonesAchieved();
		int addedHealthFromFood = milestonesAchieved * 2 * SOLCarrotConfig.getHeartsPerMilestone();

		double totalHealthModifier = healthPenalty + addedHealthFromFood;
		boolean hasChanged = prevModifier == null || prevModifier.getAmount() != totalHealthModifier;

		if (!player.level().isClientSide) {
			AttributeModifier modifier = new AttributeModifier(
				MILESTONE_HEALTH_MODIFIER_ID,
				"Health Gained from Trying New Foods",
				totalHealthModifier,
				AttributeModifier.Operation.ADDITION
			);

			updateHealthModifier(player, modifier);
		}

		return hasChanged;
	}

	@Nullable
	private static AttributeModifier getHealthModifier(Player player) {
		return maxHealthAttribute(player).getModifier(MILESTONE_HEALTH_MODIFIER_ID);
	}

	private static void updateHealthModifier(Player player, AttributeModifier modifier) {
		var oldMax = player.getMaxHealth();

		var attribute = maxHealthAttribute(player);
		attribute.removeModifier(modifier);
		attribute.addPermanentModifier(modifier);

		var newHealth = player.getHealth() * player.getMaxHealth() / oldMax;
		if (!HAS_FIRST_AID) { // This workaround breaks First Aid because it tries to distribute the health change and may kill the player that way.
			// because apparently it doesn't update unless changed
			player.setHealth(1f);
		}
		// adjust current health proportionally to increase in max health
		player.setHealth(newHealth);
	}

	private static AttributeInstance maxHealthAttribute(Player player) {
		return Objects.requireNonNull(player.getAttribute(Attributes.MAX_HEALTH));
	}

	private MaxHealthHandler() {}
}

package com.cazsius.solcarrot.tracking;

import com.cazsius.solcarrot.SOLCarrotConfig;

/** contains all relevant variables for current progress */
public final class ProgressInfo {
	/** the number of unique foods eaten */
	public final int foodsEaten;

	ProgressInfo(FoodList foodList) {
		foodsEaten = (int) foodList.getEatenFoods().stream()
			.filter(food -> SOLCarrotConfig.shouldCount(food.item))
			.count();
	}

	public boolean hasReachedMax() {
		return foodsEaten >= SOLCarrotConfig.highestMilestone();
	}

	/** the next milestone to reach, or a negative value if the maximum has been reached */
	public int nextMilestone() {
		return hasReachedMax() ? -1 : SOLCarrotConfig.milestone(milestonesAchieved());
	}

	/** the number of foods remaining until the next milestone, or a negative value if the maximum has been reached */
	public int foodsUntilNextMilestone() {
		return nextMilestone() - foodsEaten;
	}

	/** the number of milestones achieved, doubling as the index of the next milestone */
	public int milestonesAchieved() {
		return (int) SOLCarrotConfig.getMilestones().stream()
			.filter(milestone -> foodsEaten >= milestone).count();
	}
}

